  </main>
  <div v-if="selected" class="detail-overlay" @click.self="selected = null"><div class="detail-panel"><button class="detail-panel-close" aria-label="Tutup detail" @click="selected = null">×</button><img class="detail-panel-image" :src="selected.image" :alt="selected.title"><p class="detail-panel-category">{{ selected.category }} · {{ selected.duration }}</p><h2 class="detail-panel-title">{{ selected.title }}</h2><p class="detail-panel-description">{{ selected.description }}</p><p class="detail-panel-section-label">Tujuan Pembelajaran</p><p class="detail-panel-description">{{ selected.learningObjectives }}</p><div class="detail-panel-footer"><span :class="['level-badge-inline', selected.level]">{{ levelNames[selected.level] }}</span><NuxtLink :to="`/course/javascript_dasar?id=${selected.id}`" class="button-start-learning">Mulai Belajar</NuxtLink></div></div></div>
